import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"師","description":"周易正义 - 師","frontmatter":{"title":"師","description":"周易正义 - 師"},"headers":[],"relativePath":"zh/classics/zhengyi/007.md","filePath":"zh/classics/zhengyi/007.md"}'),l={name:"zh/classics/zhengyi/007.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>地水师</p></blockquote><blockquote><p>卦辞：贞，丈人吉，无咎。</p></blockquote><blockquote><p>彖曰：师，众也；贞，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之，吉又何咎矣。</p></blockquote><h1 id="師" tabindex="-1">師 <a class="header-anchor" href="#師" aria-label="Permalink to “師”">​</a></h1><p>王弼：丈人，严庄之称也。为师之正，丈人乃吉也。兴役动众无功，罪也，故吉乃无咎也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“师：贞，丈人吉，无咎”。○正义曰：“师”，众也。贞，正也。丈人谓严庄尊重之人，言为师之正，唯得严庄丈人监临主领，乃得“吉无咎”。若不得丈人监临之，无不畏惧，不能齐众，必有咎害。○注“丈人严戒之称也”至“乃无咎也”。○正义曰：“兴役动众无功，罪”者，监临师旅，当以威严，则有功劳，乃得无咎；若其不以威严，师必无功而获其罪，故云“兴役动众无功，罪”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="师-众也。贞-正也。能以众正-可以王矣。刚中而应-行险而顺-以此毒天下而民从之-吉又何咎矣-​" tabindex="-1">师，众也。贞，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下而民从之，吉又何咎矣？ ​ <a class="header-anchor" href="#师-众也。贞-正也。能以众正-可以王矣。刚中而应-行险而顺-以此毒天下而民从之-吉又何咎矣-​" aria-label="Permalink to “师，众也。贞，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下而民从之，吉又何咎矣？ ​”">​</a></h3><p>王弼：毒犹役也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“彖曰”至“又何咎矣”。○正义曰：“师，众也。贞，正也。能以众正，可以王矣”者，此释师卦之名，并明用师有功之义。但师训既多，或训为法，或训为长，恐此师名取法之与长，故特明之师训为众也。贞为正也。贞之为正，其义已见於此，复云““贞，正”者，欲见齐众必须以正，故训贞为正也。与下文为首引之势，故云“能以众正，可以王矣”。“刚中而应”者，“刚中”谓九二，而“应”谓六五。“行险而顺”者，“行险”谓下体坎也，而“顺”谓上体坤也。若刚中而无应，或有应而不刚中，或行险而不柔顺，皆不可行师得吉也。“以此毒天下而民从之，吉又何咎矣”者，毒犹役也，若用此诸德使役天下之众，人必从之以得其吉，又何无功而咎责乎？自“刚中”以下释“丈人吉，无咎”也，言丈人能备此诸德也。</p><h3 id="《象》曰-地中有水-师。君子以容民畜众。-​" tabindex="-1">《象》曰：地中有水，师。君子以容民畜众。 ​ <a class="header-anchor" href="#《象》曰-地中有水-师。君子以容民畜众。-​" aria-label="Permalink to “《象》曰：地中有水，师。君子以容民畜众。 ​”">​</a></h3><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“君子以容民畜众”者，言君子法此师卦，容纳其民，畜养其众。若为人除害，使众得宁，此则“容民畜众”也。又为师之，主虽尚威严，当赦其小过，不可纯用威猛於军师之中，亦是容民畜众之义。所以《象》称“地中有水”，欲见地能包水，水又众大，是容民畜众之象。若其不然，或当云“地在水上”，或云“上地下水”，或云“水上有地”。今云“地中有水”，盖取容、畜之义也。</p><h2 id="初六-师出以律-否臧凶。-​" tabindex="-1">初六：师出以律，否臧凶。 ​ <a class="header-anchor" href="#初六-师出以律-否臧凶。-​" aria-label="Permalink to “初六：师出以律，否臧凶。 ​”">​</a></h2><p>王弼：为师之始，齐师者也。齐众以律，失律则散。故师出以律，律不可失。失律而臧，何异於否？失令有功，法所不赦。故师出不以律，否臧皆凶。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>“初六师出”至“否臧凶”。○正义曰：“初六师出以律”者，律，法也。初六为师之始，是整齐师众者也。既齐整师众，使师出之时，当须以其法制整齐之，故云“师出以律”也。“否臧凶”者，若其失律行师，无问否之与臧，皆为凶也。“否”谓破败，“臧”谓有功。然“否”为破败，即是凶也。何须更云“否臧凶”者，本意所明，虽臧亦凶。“臧”文既单，故以“否”配之，欲盛言臧凶，不可单言，故云否之与臧，皆为凶也。○注“为师之始”至“否臧皆凶”。○正义曰：“为师之始，齐师者也”者，以师之初爻，故云“为师之始”。在师之首，先唱发始，是齐整师众者也。“失律而臧，何异於否”者，若弃失法律，不奉法而行，虽有功而臧，何异於否也？“失令有功，法所不赦”者，解“何异於否”之义。令则法律也。若失此法令，虽有功劳，军法所不容赦，故云“何异於否”。然阃外之事，将军所载，临事制宜，不必皆依君命，何得有功“法所不赦”者：凡为师之体，理非一端，量事制宜，随时进退，此则将军所制，随时施行。若苟顺私情，故违君命，犯律触法，则事不可赦耳。</p><h3 id="《象》曰-师出以律-失律凶也。-​" tabindex="-1">《象》曰：“师出以律”，失律凶也。 ​ <a class="header-anchor" href="#《象》曰-师出以律-失律凶也。-​" aria-label="Permalink to “《象》曰：“师出以律”，失律凶也。 ​”">​</a></h3><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰“失律凶”者，释“师出以律”之义。言所以必须以律者，以其失律则凶。反经之文，以明经义。</p><h2 id="九二-在师中-吉-无咎-王三锡命。-​" tabindex="-1">九二：在师中，吉，无咎，王三锡命。 ​ <a class="header-anchor" href="#九二-在师中-吉-无咎-王三锡命。-​" aria-label="Permalink to “九二：在师中，吉，无咎，王三锡命。 ​”">​</a></h2><p>王弼：以刚居中，而应於上，在师而得其中者也。承上之宠，为师之主，任大役重，无功则凶，故吉乃无咎也。行师得吉，莫善怀邦，邦怀众服，锡莫重焉，故乃得成命。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“九二”至“王三锡命”。○正义曰：“在师中吉”者，以刚居中而应於五，是“在师中吉”也。“无咎”者，承上之宠，为师之主，任大役重，无功则凶，故吉乃无咎。“王三锡命”者，以其有功，故王三加锡命。○注“以刚居中”至“故乃得成命”。○正义曰：“在师而得中”者，观注之意，以“在师中”为句，其“吉”字属下；观《象》之文，“在师中吉，承天宠”者，则似“吉”字属上。此“吉”之一字上下兼该，故注文属下，《象》文属上，但《象》略其“无咎”之字，故“吉”属“师中”也。“故乃得成命”者，案《曲礼》云：“三赐不及车马。”一命受爵，再命受服，三命受车马。三赐三命，而尊之得成，故“乃得成命”也。</p><h3 id="《象》曰-在师中吉-承天宠也。-王三锡命-怀万邦也。-​" tabindex="-1">《象》曰：“在师中吉”，承天宠也。“王三锡命”，怀万邦也。 ​ <a class="header-anchor" href="#《象》曰-在师中吉-承天宠也。-王三锡命-怀万邦也。-​" aria-label="Permalink to “《象》曰：“在师中吉”，承天宠也。“王三锡命”，怀万邦也。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“承天宠”者，释“在师中吉”之义也。正谓承受五之恩宠，故“中吉”也。“怀万邦也”者，以其有功，能招怀万邦，故被“王三锡命”也。</p><h2 id="六三-师或舆尸-凶。-​" tabindex="-1">六三：师或舆尸，凶。 ​ <a class="header-anchor" href="#六三-师或舆尸-凶。-​" aria-label="Permalink to “六三：师或舆尸，凶。 ​”">​</a></h2><p>王弼：以阴处阳，以柔乘刚，进则无应，退无所守，以此用师，宜获“舆尸”之凶。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>“六三师或舆尸凶”。○正义曰：以阴处阳，以柔乘刚，进无所应，退无所守，以此用师，或有舆尸之凶。○注“以阴处阳”至“舆尸之凶”。○正义曰：“退无所守”者，倒退而下，乘二之刚，已又以阴居阳，是“退无所守”。</p><h3 id="《象》曰-师或舆尸-大无功也。-​" tabindex="-1">《象》曰：“师或舆尸”，大无功也。 ​ <a class="header-anchor" href="#《象》曰-师或舆尸-大无功也。-​" aria-label="Permalink to “《象》曰：“师或舆尸”，大无功也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“大无功也”者，释“舆尸”之义，以其舆尸，则大无功也。</p><h2 id="六四-师左次-无咎。-​" tabindex="-1">六四：师左次，无咎。 ​ <a class="header-anchor" href="#六四-师左次-无咎。-​" aria-label="Permalink to “六四：师左次，无咎。 ​”">​</a></h2><p>王弼：得位而无应，无应不可以行，得位则可以处，故左次之，而无咎也。行师之法，欲右背高，故左次之。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>“六四，师左次，无咎”。○正义曰：六四得位而无应，无应不可以行，得位则可以处，故云“师左次，无咎”。故师在高险之左，以次止则无凶咎也。○注“行师之法”至“故左次之”。○正义曰：“行师之法，欲右背高”者，此兵法也。故《汉书》韩信云：“兵法欲右背山陵，前左水泽。”</p><h3 id="《象》曰-左次无咎-未失常也。虽不能有获-足以不失其常也。-​" tabindex="-1">《象》曰：“左次无咎”，未失常也。虽不能有获，足以不失其常也。 ​ <a class="header-anchor" href="#《象》曰-左次无咎-未失常也。虽不能有获-足以不失其常也。-​" aria-label="Permalink to “《象》曰：“左次无咎”，未失常也。虽不能有获，足以不失其常也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未失常”者，释“无咎”之义，以其虽未有功，未失常道。</p><h2 id="六五-田有禽-利执言-无咎。长子帅师-弟子舆尸-贞凶。-​" tabindex="-1">六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。 ​ <a class="header-anchor" href="#六五-田有禽-利执言-无咎。长子帅师-弟子舆尸-贞凶。-​" aria-label="Permalink to “六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。 ​”">​</a></h2><p>王弼：处师之时，柔得尊位，阴不先唱，柔不犯物，犯而后应，往必得直，故“田有禽”也。物先犯己，故可以执言而无咎也。柔非军帅，阴非刚武，故不躬行，必以授也。授不得王，则众不从，故“长子帅师”可也。弟子之凶，故其宜也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“六五田有禽”至“舆尸贞凶”。○正义曰：“田有禽，利执言”者，柔得尊位，阴不先唱，柔不犯物，犯而后应，往必得直，故往即有功。犹如田中有禽而来犯苗，若往猎之，则无咎过也。人之修田，非禽之所犯。王者守国，非叛者所乱。禽之犯苗，则可猎取。叛人乱国，则可诛之。此假他象以喻人事，故“利执言，无咎”，已不直则有咎。己今得直，故可以执此言往问之而无咎也。“长子帅师，弟子舆尸，贞凶”者，以已是柔，不可为军帅。已又是阴，身非刚武，不可以亲行，故须役任长子、弟子之等。若任役长子，则可以帅师。若任用弟子，则军必破败而舆尸，是为正之凶。庄氏云：“‘长子’谓九二，德长於人。‘弟子’谓六三，德劣於物。”今案：《象》辞云“长子帅师，以中行也”，是九二居中也。“弟子舆尸，使不当也”，谓六三失位也。○注至“往必得直”。○正义曰：“往必得直”者，见犯乃得欲往征之，则於理正直，故云“往必得直”。</p><h3 id="《象》曰-长子帅师-以中行也。-弟子舆尸-使不当也。-​" tabindex="-1">《象》曰：“长子帅师”，以中行也。“弟子舆尸”，使不当也。 ​ <a class="header-anchor" href="#《象》曰-长子帅师-以中行也。-弟子舆尸-使不当也。-​" aria-label="Permalink to “《象》曰：“长子帅师”，以中行也。“弟子舆尸”，使不当也。 ​”">​</a></h3><h2 id="上六-大君有命-开国承家-小人勿用。-​" tabindex="-1">上六：大君有命，开国承家，小人勿用。 ​ <a class="header-anchor" href="#上六-大君有命-开国承家-小人勿用。-​" aria-label="Permalink to “上六：大君有命，开国承家，小人勿用。 ​”">​</a></h2><p>王弼：处师之极，师之终也。大君之命，不失功也。开国承家，以宁邦也。小人勿用，非其道也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>“上六大君有命”至“小人勿用”。○正义曰：“大君有命”者，上六处师之极，是师之终竟也。“大君”谓天子也，言天子爵命此上六，若其功大，使之开国为诸侯；若其功小，使之承家为卿大夫。“小人勿用”者，言开国承家，须用君子，勿用小人也。</p><h3 id="《象》曰-大君有命-以正功也。-小人勿用-必乱邦也。-​" tabindex="-1">《象》曰：“大君有命”，以正功也。“小人勿用”，必乱邦也。 ​ <a class="header-anchor" href="#《象》曰-大君有命-以正功也。-小人勿用-必乱邦也。-​" aria-label="Permalink to “《象》曰：“大君有命”，以正功也。“小人勿用”，必乱邦也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“大君有命，以正功也”者，正此上六之功也。“小人勿用，必乱邦也”者，若用小人，必乱邦国，故不得用小人也。</p>',55)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
